package com.kuaixietech.integrationsdk.social;
import com.fasterxml.jackson.databind.*;
import com.kuaixietech.integration.IntegrationHttp;
import java.net.*;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.*;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import org.springframework.stereotype.Component;
/** Official mini-program identity and subscription APIs. No fake sandbox, account linking or consent synthesis. */
@Component
public class WechatMiniProtocol {
 private final IntegrationHttp http;private final ObjectMapper json;private final Clock clock;private final Map<String,Token> tokens=new ConcurrentHashMap<>();
 private record Token(String value,Instant expiresAt){}
 public record MiniSession(String appId,String openId,String unionId){@Override public String toString(){return "MiniSession[appId="+appId+", identity=REDACTED]";}}
 public record Recipient(String appId,String openId){}
 public record DeliveryReceipt(boolean accepted,String providerCode){}
 @org.springframework.beans.factory.annotation.Autowired public WechatMiniProtocol(IntegrationHttp http,ObjectMapper json){this(http,json,Clock.systemUTC());}
 public WechatMiniProtocol(IntegrationHttp http,ObjectMapper json,Clock clock){this.http=http;this.json=json;this.clock=clock;}
 public MiniSession session(SocialServiceContext context,String code){context.require("MINIAPP","weixin",false);String app=appId(context);if(code==null||!code.matches("[A-Za-z0-9_-]{4,128}"))throw new IllegalArgumentException("WECHAT_LOGIN_CODE_INVALID");var request=HttpRequest.newBuilder(URI.create("https://api.weixin.qq.com/sns/jscode2session?appid="+encode(app)+"&secret="+encode(context.required("app_secret"))+"&js_code="+encode(code)+"&grant_type=authorization_code")).timeout(Duration.ofSeconds(10)).GET().build();JsonNode result=read(http.send(request));rejectError(result);String open=result.path("openid").asText(),union=result.path("unionid").isTextual()?result.path("unionid").asText():null;if(!validIdentity(open)||union!=null&&!validIdentity(union))throw new IllegalStateException("WECHAT_IDENTITY_RESPONSE_INVALID");return new MiniSession(app,open,union);}
 /** The business caller must derive recipient and consent from its own authenticated records, not arbitrary client inputs. */
 public DeliveryReceipt subscribe(SocialServiceContext context,Recipient recipient,String page,Map<String,String> data,String language,boolean consentConfirmed){context.require("SUBSCRIBE","weixin",false);String app=appId(context);if(!consentConfirmed)throw new IllegalArgumentException("WECHAT_SUBSCRIPTION_CONSENT_REQUIRED");if(recipient==null||!app.equals(recipient.appId())||!validIdentity(recipient.openId()))throw new IllegalArgumentException("WECHAT_RECIPIENT_APP_MISMATCH");String template=context.required("template_id");if(!template.matches("[A-Za-z0-9_-]{8,128}")||data==null||data.isEmpty()||data.size()>20||!Set.of("zh_CN","en_US","zh_HK","zh_TW").contains(language))throw new IllegalArgumentException("WECHAT_SUBSCRIPTION_INPUT_INVALID");var mapped=new LinkedHashMap<String,Object>();for(var field:data.entrySet()){if(field.getKey()==null||!field.getKey().matches("(?:thing|number|letter|symbol|character_string|time|date|amount|phone_number|car_number|name|phrase)[0-9]{1,3}")||field.getValue()==null||field.getValue().isBlank()||field.getValue().codePointCount(0,field.getValue().length())>140)throw new IllegalArgumentException("WECHAT_TEMPLATE_DATA_INVALID");mapped.put(field.getKey(),Map.of("value",field.getValue()));}var payload=new LinkedHashMap<String,Object>();payload.put("touser",recipient.openId());payload.put("template_id",template);payload.put("data",mapped);payload.put("miniprogram_state","formal");payload.put("lang",language);if(page!=null&&!page.isBlank()){if(page.length()>512||page.startsWith("/")||!page.matches("[A-Za-z0-9_/-]+(?:\\?[A-Za-z0-9_=&%.-]+)?"))throw new IllegalArgumentException("WECHAT_PAGE_INVALID");payload.put("page",page);}String token=accessToken(context);JsonNode result=read(http.send(post("https://api.weixin.qq.com/cgi-bin/message/subscribe/send?access_token="+encode(token),payload)));if(!result.path("errcode").isIntegralNumber())throw new IllegalStateException("WECHAT_SUBSCRIPTION_RESULT_UNCONFIRMED");String code=result.path("errcode").asText();if(!"0".equals(code))return new DeliveryReceipt(false,code);return new DeliveryReceipt(true,"0");}
 private String accessToken(SocialServiceContext context){String app=appId(context),secret=context.required("app_secret"),key=app+":"+context.mode()+":"+context.revision()+":"+hash(secret);Token cached=tokens.get(key);if(cached!=null&&cached.expiresAt().isAfter(clock.instant()))return cached.value();synchronized(tokens){cached=tokens.get(key);if(cached!=null&&cached.expiresAt().isAfter(clock.instant()))return cached.value();JsonNode result=read(http.send(post("https://api.weixin.qq.com/cgi-bin/stable_token",Map.of("grant_type","client_credential","appid",app,"secret",secret,"force_refresh",false))));rejectError(result);String token=result.path("access_token").asText();JsonNode expiry=result.get("expires_in");if(token.isBlank()||token.length()>4096||expiry==null||!expiry.isIntegralNumber()||expiry.asLong()<60||expiry.asLong()>7200)throw new IllegalStateException("WECHAT_ACCESS_TOKEN_INVALID");tokens.entrySet().removeIf(e->e.getValue().expiresAt().isBefore(clock.instant()));if(tokens.size()>200)tokens.clear();tokens.put(key,new Token(token,clock.instant().plusSeconds(expiry.asLong()-60)));return token;}}
 private HttpRequest post(String url,Object value){try{return HttpRequest.newBuilder(URI.create(url)).timeout(Duration.ofSeconds(10)).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(json.writeValueAsString(value))).build();}catch(Exception e){throw new IllegalArgumentException("WECHAT_REQUEST_INVALID");}}
 private JsonNode read(String value){try{JsonNode result=json.readTree(value);if(result==null||!result.isObject())throw new IllegalArgumentException();return result;}catch(Exception e){throw new IllegalStateException("WECHAT_PROVIDER_RESPONSE_INVALID");}}
 private void rejectError(JsonNode result){if(result.has("errcode")&&(!result.path("errcode").isIntegralNumber()||result.path("errcode").asLong()!=0))throw new IllegalStateException("WECHAT_PROVIDER_REJECTED");}
 private String appId(SocialServiceContext context){String app=context.required("app_id");if(!app.matches("wx[A-Za-z0-9]{8,30}"))throw new IllegalArgumentException("WECHAT_APP_ID_INVALID");return app;}
 private boolean validIdentity(String id){return id!=null&&id.matches("[A-Za-z0-9_-]{8,128}");}
 private static String encode(String value){return URLEncoder.encode(value,StandardCharsets.UTF_8);}
 private static String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException("WECHAT_CACHE_KEY_UNAVAILABLE");}}
}
